#pragma once
#include <string>
#include <set>
#include <unordered_map>
#include <vector>
#include <stdexcept>
#include <fstream>
#include <sstream>
#include <algorithm>
#include <cctype>


class INIReader {
public:
    INIReader() = default;

    INIReader(const std::string& filename) {
        std::ifstream file(filename);
        if (!file.is_open()) {
            _error = -1;
            throw std::runtime_error("Failed to open file");
        }
        Parse(std::string((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>()));
    }

    INIReader(std::FILE* file) {
        if (!file) {
            _error = -1;
            throw std::runtime_error("Failed to open file");
        }
        std::string content((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
        Parse(content);
    }

    int ParseError() const {
        return _error;
    }

    std::set<std::string> Sections() const {
        std::set<std::string> sections;
        for (const auto& pair : _values) {
            sections.insert(pair.first);
        }
        return sections;
    }

    std::set<std::string> Keys(const std::string& section) const {
        const auto& sec = GetSection(section);
        std::set<std::string> keys;
        for (const auto& pair : sec) {
            keys.insert(pair.first);
        }
        return keys;
    }

    std::unordered_map<std::string, std::string> Get(const std::string& section) const {
        return GetSection(section);
    }

    template <typename T = std::string>
    T Get(const std::string& section, const std::string& name) const {
        return Converter<T>(FindEntry(section, name));
    }

    template <typename T>
    T Get(const std::string& section, const std::string& name, T&& default_v) const {
        try {
            return Get<T>(section, name);
        } catch (const std::runtime_error&) {
            return std::forward<T>(default_v);
        }
    }

    template <typename T = std::string>
    std::vector<T> GetVector(const std::string& section, const std::string& name) const {
        std::vector<std::string> vec;
        std::stringstream ss(FindEntry(section, name));
        std::string item;
        while (ss >> item) {
            vec.push_back(item);
        }
        return std::vector<T>(vec.begin(), vec.end());
    }

    template <typename T>
    std::vector<T> GetVector(const std::string& section, const std::string& name, const std::vector<T>& default_v) const {
        try {
            return GetVector<T>(section, name);
        } catch (const std::runtime_error&) {
            return default_v;
        }
    }

    template <typename T = std::string>
    void InsertEntry(const std::string& section, const std::string& name, const T& v) {
        if (_values[section].find(name) != _values[section].end()) {
            throw std::runtime_error("Key already exists");
        }
        _values[section][name] = V2String(v);
    }

    template <typename T = std::string>
    void InsertEntry(const std::string& section, const std::string& name, const std::vector<T>& vs) {
        if (_values[section].find(name) != _values[section].end()) {
            throw std::runtime_error("Key already exists");
        }
        _values[section][name] = Vec2String(vs);
    }

    template <typename T = std::string>
    void UpdateEntry(const std::string& section, const std::string& name, const T& v) {
        FindEntry(section, name) = V2String(v);
    }

    template <typename T = std::string>
    void UpdateEntry(const std::string& section, const std::string& name, const std::vector<T>& vs) {
        FindEntry(section, name) = Vec2String(vs);
    }

protected:
    template <typename T>
    T Converter(const std::string& s) const {
        std::stringstream ss(s);
        T value;
        if (!(ss >> value)) {
            throw std::runtime_error("Failed to convert");
        }
        return value;
    }

    bool BoolConverter(std::string s) const {
        std::transform(s.begin(), s.end(), s.begin(), ::tolower);
        if (s == "true" || s == "1") {
            return true;
        } else if (s == "false" || s == "0") {
            return false;
        }
        throw std::runtime_error("Invalid boolean value");
    }

    template <typename T>
    std::string V2String(const T& v) const {
        std::stringstream ss;
        ss << v;
        return ss.str();
    }

    template <typename T>
    std::string Vec2String(const std::vector<T>& v) const {
        std::stringstream ss;
        for (size_t i = 0; i < v.size(); ++i) {
            if (i > 0) {
                ss << " ";
            }
            ss << V2String(v[i]);
        }
        return ss.str();
    }

private:
    const std::unordered_map<std::string, std::string>& GetSection(const std::string& section) const {
        auto it = _values.find(section);
        if (it == _values.end()) {
            throw std::runtime_error("Section not found");
        }
        return it->second;
    }

    std::string& FindEntry(const std::string& section, const std::string& name) {
        auto& sec = _values[section];
        auto it = sec.find(name);
        if (it == sec.end()) {
            throw std::runtime_error("Key not found");
        }
        return it->second;
    }

    void Parse(std::string_view content) {
        std::istringstream iss(std::string(content));
        std::string line;
        std::string current_section;
        int line_number = 0;
        while (std::getline(iss, line)) {
            ++line_number;
            size_t start = line.find_first_not_of(" \t\r\n");
            if (start == std::string::npos || line[start] == ';' || line[start] == '#') {
                continue;
            }
            if (line[start] == '[') {
                size_t end = line.find(']', start);
                if (end != std::string::npos) {
                    current_section = line.substr(start + 1, end - start - 1);
                } else {
                    _error = line_number;
                    return;
                }
            } else {
                size_t equal_pos = line.find_first_of("=:", start);
                if (equal_pos != std::string::npos) {
                    std::string key = line.substr(start, equal_pos - start);
                    std::string value = line.substr(equal_pos + 1);
                    key.erase(std::remove_if(key.begin(), key.end(), ::isspace), key.end());
                    value.erase(0, value.find_first_not_of(" \t\r\n"));
                    size_t comment_pos = value.find_first_of(";# ");
                    if (comment_pos != std::string::npos) {
                        value.erase(comment_pos);
                    }
                    _values[current_section][key] = value;
                } else {
                    _error = line_number;
                    return;
                }
            }
        }
    }

private:
    int _error = 0;
    std::unordered_map<std::string, std::unordered_map<std::string, std::string>> _values;
};
